/**
 * Build the dagre layout bundle the state-chart's browser pass uses.
 *
 * WHY THIS EXISTS AT ALL — the `.toString()` constraint.
 *
 * `installStateChartLayout` is serialised into the emulator's bootstrap
 * `<script>` via `Function.prototype.toString()` (state-chart.transform.js).
 * A stringified function carries NO closure and NO module scope, so the pass
 * cannot `require('dagre-d3-es')` and cannot close over an imported symbol —
 * whatever it needs must already exist as a GLOBAL in the document it lands in.
 *
 * So dagre reaches the three render paths two different ways, and both end at
 * the same global:
 *
 *   · emulator / CLI export — this file's IIFE is prepended to the serialised
 *     pass, so `globalThis.__latticeDagre` exists before the pass runs.
 *   · runtime bundle + docs playground — `lib/core/dagre-layout.js` imports
 *     dagre normally and esbuild inlines it; importing it sets the same global.
 *
 * The pass reads `globalThis.__latticeDagre` and falls back to the numbered
 * column when it is absent, so a host that loads neither degrades to today's
 * layout rather than rendering nothing.
 *
 * OUTPUT IS GENERATED, NOT COMMITTED — same contract as the docs-site bundles
 * (engineering/decisions/2026-08-17-generated-bundles-uncommitted.md): a
 * minified bundle on one line makes every concurrent PR conflict. `prepare`
 * builds it, so a fresh clone and `npm publish` both have it.
 */
const path = require('path');
const fs = require('fs');
const { execFileSync } = require('child_process');

const ROOT = path.resolve(__dirname, '..');
const OUT = path.join(ROOT, 'lib', 'core', 'dagre-bundle.generated.js');
const ENTRY = path.join(ROOT, '.dagre-entry.tmp.mjs');

// Only `layout` and `Graph` are reachable, which is what keeps this at ~62KB
// against the package's full surface: esbuild tree-shakes lodash-es down to the
// few dozen functions the layered algorithm actually calls.
const ENTRY_SRC = `
import * as dagre from 'dagre-d3-es/src/dagre/index.js';
import { Graph } from 'dagre-d3-es/src/graphlib/index.js';
globalThis.__latticeDagre = { layout: dagre.layout, Graph };
`;

function build({ check = false } = {}) {
  fs.writeFileSync(ENTRY, ENTRY_SRC);
  let iife;
  try {
    iife = execFileSync(
      path.join(ROOT, 'node_modules', '.bin', 'esbuild'),
      [ENTRY, '--bundle', '--minify', '--format=iife', '--platform=browser', '--log-level=error'],
      { cwd: ROOT, encoding: 'utf8', maxBuffer: 32 * 1024 * 1024 },
    );
  } finally {
    fs.rmSync(ENTRY, { force: true });
  }

  // The IIFE is exported as a STRING (not executed here): the transform
  // concatenates it ahead of the serialised pass. JSON.stringify is the escape —
  // the bundle contains quotes, backslashes and newlines, and a template literal
  // would also have to escape `${`, which minified code genuinely contains.
  const out =
    '/* Auto-generated by tools/build-dagre-bundle.js — DO NOT EDIT.\n' +
    '   Source: dagre-d3-es (MIT) — see assets/licenses/MIT-dagre-d3-es.txt.\n' +
    '   Rebuild: node tools/build-dagre-bundle.js\n' +
    '   SPDX-License-Identifier: AGPL-3.0-only\n' +
    '   Copyright (c) 2025-2026 SlideWright\n*/\n' +
    'module.exports = { DAGRE_IIFE: ' + JSON.stringify(iife) + ' };\n';

  if (check) {
    const cur = fs.existsSync(OUT) ? fs.readFileSync(OUT, 'utf8') : '';
    if (cur !== out) {
      console.error('dagre-bundle STALE — run `node tools/build-dagre-bundle.js`');
      process.exit(1);
    }
    console.log(`dagre-bundle OK — ${(iife.length / 1024).toFixed(1)} KB IIFE.`);
    return;
  }
  fs.writeFileSync(OUT, out);
  console.log(`[build-dagre-bundle] lib/core/dagre-bundle.generated.js (${(iife.length / 1024).toFixed(1)} KB IIFE)`);
}

if (require.main === module) build({ check: process.argv.includes('--check') });
module.exports = { build, OUT };
